const bt=(l,f,d)=>`<button class="b" ${d?'disabled':''} onclick="${f};ren()">${l}</button>`,row=(a,b)=>`<div class="r"><div>${a}</div><div>${b}</div></div>`,card=(t,b)=>`<div class="c"><h3>${t}</h3>${b}</div>`;
