function buy(id,a){const f=a*(.003-Math.min(.002,S.sk.fin*.0002));if(!pay(a))return;const h=S.hold[id]||(S.hold[id]={q:0,c:0});h.q+=(a-f)/S.px[id];h.c+=a;log('Beli '+id+' '+R(a));S.thist=S.thist||[];S.thist.unshift('Hari '+S.d+' · Beli '+id+' · '+R(a));if(S.thist.length>30)S.thist.length=30}
function sell(id,p){const h=S.hold[id];if(!h)return;const q=h.q*p,v=q*S.px[id]*(1-.003);S.cash+=v;h.c*=1-p;h.q-=q;if(h.q<1e-9)delete S.hold[id];log('Jual '+id+' '+R(v));S.thist=S.thist||[];S.thist.unshift('Hari '+S.d+' · Jual '+id+' · '+R(v));if(S.thist.length>30)S.thist.length=30}
function course(k){const l=S.sk[k];if(l>=10)return;const c=3e5*(l+1)**1.5;if(S.hrs>=3&&S.cash>=c){pay(c);use(3);S.sk[k]++;S.hap=cl(S.hap+1);log(' '+SKN[k]+' naik ke level '+(l+1));maybeTalk('course','mentor',.3)}else log('Butuh '+R(c)+' dan 3 jam')}
function gig(k){const g={ojek:[3,()=>rn(1e5,2e5),4],free:[3,()=>(1.5e5+S.sk.tech*7e4+S.sk.des*5e4)*(1+S.it*.06),5],jual:[2,()=>rn(6e4,2.5e5)*(1+S.sk.biz*.1),3]}[k];if(!use(g[0]))return;const v=g[1]()*(1-S.str/300);S.cash+=v;S.str=cl(S.str+g[2]);log(' Kerja sampingan +'+R(v));maybeTalk('gig','client',.3)}
function leis(k){const o={hobi:[2,5e4,-10,6,0],rest:[4,0,-12,2,6],gym:[2,3e4,-4,2,3],lib:[10,3e6,-40,25,4]}[k];if(S.hrs<o[0])return log(' Waktu tidak cukup');if(!pay(o[1]))return;S.hrs-=o[0];S.str=cl(S.str+o[2]);S.hap=cl(S.hap+o[3]);S.hp=cl(S.hp+o[4]);if(k=='hobi'||k=='lib')maybeTalk('leis','friend',.3)}
function popa(k){const o={sos:[1,0,rn(1,3)],inf:[0,5e5,4],amal:[1,5e6,8],tv:[2,2e7,12]}[k];if(S.hrs<o[0])return log(' Waktu tidak cukup');if(!pay(o[1]))return;S.hrs-=o[0];S.pop=cl(S.pop+o[2]*(1+S.sk.mkt*.08));maybeTalk('popa','fan',.3)}
function bond(i,a){if(!pay(a))return;const b=BD[i];S.bonds.push({n:b[0],amt:a,y:b[1],st:S.d,end:S.d+b[2],rk:b[3]})}
function bank(k,a){if(k=='dep'){a=a=='all'?S.cash:a;if(S.cash>=a&&a>0){S.cash-=a;S.dep+=a}}else if(k=='wd'){S.cash+=S.dep;S.dep=0}else if(k=='loan'){const lim=Math.max(5e6,nw()*.5);if(S.loan+a<=lim){S.loan+=a;S.cash+=a}else log('Melebihi batas kredit '+R(lim))}else{const p=Math.min(S.cash,S.loan);S.cash-=p;S.loan-=p}}
function exchangeDia(n){n=Math.min(Math.round(n),S.dia||0);if(n<=0)return log('Tidak ada berlian untuk ditukar');S.dia-=n;S.cash+=n*5e6;log('Menukar '+n+' berlian menjadi '+R(n*5e6))}
function buyP(i){const p=PR[i][1]*S.pi;if(pay(p))S.props.push(i)}
function sellP(x){const i=S.props.splice(x,1)[0];S.cash+=PR[i][1]*S.pi*.97}
function startBuild(i){const p=PR[i],cost=Math.round(p[1]*S.pi*PRB[i][0]);if(!pay(cost))return;S.builds=S.builds||[];S.builds.push({ty:i,start:S.d,end:S.d+PRB[i][1],cost});log('Mulai membangun '+p[0]+', selesai '+PRB[i][1]+' hari lagi')}
function startMega(i){const p=PM[i];if(S.net<p[4])return log('Jaringan minimal '+p[4]+' dibutuhkan');if(S.pop<p[5])return log('Popularitas minimal '+p[5]+' dibutuhkan');if(S.office<p[6])return log('Perlu menjabat minimal '+OF[p[6]-1][0]);if(!pay(p[1]))return;S.megaBuilds=S.megaBuilds||[];S.megaBuilds.push({ty:i,start:S.d,end:S.d+p[3]});log('Memulai megaproyek: '+p[0]+', selesai '+p[3]+' hari lagi')}
function sellMega(x){const i=S.megas.splice(x,1)[0];const v=Math.round(PM[i][1]*.5);S.cash+=v;log('Melepas hak kelola '+PM[i][0]+' seharga '+R(v))}
function hire(n){const s=ST.find(x=>x[0]==n);if(S.staff.includes(n))S.staff=S.staff.filter(x=>x!=n);else{S.staff.push(n);if(n=='Asisten Pribadi')S.hrs+=2}}
function runP(i){const o=OF[i];S.camp={i,sp:o[3],end:S.d+14}}
function bribe(){if(S.office<1)return;if(!pay(5e6))return;S.tax=Math.max(0,S.tax-.02);if(Math.random()<.25-S.sk.law*.02){S.pop=cl(S.pop-15);S.cash-=1e7;log(' Suap terbongkar! Denda Rp 10 jt, popularitas anjlok')}}
const hs=(a,b,c)=>{let h=(a*73856093)^(b*19349663)^(c*83492791);h=Math.imul(h^(h>>>13),1274126177);return((h^(h>>>16))>>>0)/4294967295};
function comps(b,lv){const t=BT[b.ty],N=['Kuliner','Ritel','Digital','Manufaktur','Kreatif','Trading','Konsultan'][b.ty],P={local:['Maju Jaya','Berkah Abadi','Sumber Rejeki','Mitra Lokal','Cahaya Baru'],nat:['Nusantara Prima','Garuda Mandiri','Indo Sentosa','Bhinneka Utama','Samudra Raya'],glob:['Atlas Global','Meridian Corp','Helix International','Orion Group','Vertex Worldwide']}[lv],M={local:[1.5,3,6,10,16],nat:[60,110,180,260,380],glob:[700,1300,2200,4000,7000]}[lv],mo=S.d/30|0;return P.map((p,i)=>({n:p+' '+N,rev:t[1]*t[3]*14*M[i]*(.8+.4*hs(b.id||1,lv.length*7+i,mo))*S.eco,mg:1-(t[2]+.1)-.12+(hs(i+3,b.ty+1,mo)-.5)*.1}))}
function cmpv(b){const l=b.l,tb=[['local','Lokal'],['nat','Nasional'],['glob','Global']].map(x=>`<button class="b" style="${BMK==x[0]?'background:var(--t);color:var(--bg)':''}" onclick="BMK='${x[0]}';ren()">${x[1]}</button>`).join('');if(!l)return card('Perbandingan Pasar',tb+'<div class="m" style="margin-top:8px">Jalankan bisnis minimal satu hari untuk melihat perbandingan.</div>');
const our={n:b.name+' (Anda)',rev:l.rev,mg:l.rev?(l.pr-l.tax)/l.rev:0,me:1},all=[...comps(b,BMK),our].sort((x,y)=>y.rev-x.rev),mx=all[0].rev||1,rk=all.findIndex(x=>x.me)+1,tot=all.reduce((a,x)=>a+x.rev,0);
const rows=all.map((x,i)=>`<div style="padding:6px 0;border-bottom:1px solid var(--l)"><div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap"><span>${i+1}. <b>${x.n}</b></span><span class="m">${R(x.rev)}/hari · margin ${(x.mg*100).toFixed(0)}%</span></div><div class="bar"><i style="width:${Math.max(1,x.rev/mx*100)}%;background:${x.me?'var(--a)':'var(--m)'}!important"></i></div></div>`).join('');
const nx=rk>1?all[rk-2]:null,msg=nx?'Selisih omzet ke peringkat '+(rk-1)+' ('+nx.n+'): '+R(nx.rev-our.rev)+'/hari.':'Anda memimpin kelompok ini.';
return card('Perbandingan Pasar',tb+'<div style="margin-top:8px">'+rows+'</div>'+row('Peringkat Anda','<b>#'+rk+' dari '+all.length+'</b>')+row('Pangsa omzet kelompok','<b>'+(our.rev/tot*100).toFixed(1)+'%</b>')+'<div class="m">'+msg+' Pesaing bergerak mengikuti kondisi ekonomi. Data diperbarui tiap bulan.</div>')}
