function openShort(id,a){if(!pay(a))return;S.shorts=S.shorts||{};const px=S.px[id],cur=S.shorts[id]||{q:0,val:0,avg:px};cur.avg=(cur.avg*cur.val+px*a)/(cur.val+a);cur.q+=a/px;cur.val+=a;S.shorts[id]=cur;log('Short '+id+' senilai '+R(a));S.thist=S.thist||[];S.thist.unshift('Hari '+S.d+' · Short '+id+' · '+R(a));if(S.thist.length>30)S.thist.length=30}
function closeShort(id,frac){const h=S.shorts&&S.shorts[id];if(!h)return;const px=S.px[id],q=h.q*frac,principal=h.val*frac,pl=(h.avg-px)*q,payout=Math.max(0,principal+pl);S.cash+=payout;h.q-=q;h.val-=principal;if(h.q<1e-9)delete S.shorts[id];log('Tutup short '+id+' · '+(pl>=0?'untung':'rugi')+' '+R(pl));S.thist=S.thist||[];S.thist.unshift('Hari '+S.d+' · Tutup short '+id+' · '+(pl>=0?'+':'')+R(pl));if(S.thist.length>30)S.thist.length=30}
function placeOrder(aid,kind,price,amt){S.orders=S.orders||[];S.oid=(S.oid||0)+1;S.orders.push({id:S.oid,aid,kind,price,amt});log('Order '+(kind=='buy'?'beli':'jual')+' '+aid+' dipasang @ '+R(price))}
function cancelOrder(id){S.orders=(S.orders||[]).filter(o=>o.id!=id)}
function foundBiz(){if(S.bizs.length>=5)return log('Maksimal 5 bisnis boleh berjalan bersamaan. Jual salah satu dulu.');const cap=bcap(NB);if(S.hrs<2)return log('Butuh 2 jam untuk mendirikan bisnis');if(!pay(cap))return;S.hrs-=2;S.bn=(S.bn||0)+1;const nm=(NB.name||'').trim().slice(0,40)||(BT[NB.ty][0]+' #'+S.bn);S.bizs.push({id:S.bn,ty:NB.ty,name:nm,sc:NB.sc,mgmt:NB.mg,price:1,qual:1,mk:0,mg:0});log('Bisnis baru: '+nm+', skala '+SC[NB.sc][0]);NB.name='';BV=S.bizs.length-1}
function renameBiz(i){const b=S.bizs[i];if(!b)return;const v=prompt('Nama baru untuk perusahaan ini:',b.name);if(v==null||!v.trim())return;b.name=v.trim().slice(0,40);log('Bisnis diganti nama menjadi '+b.name)}
function renameUser(){const v=prompt('Nama Anda:',S.uname||'');if(v==null)return;S.uname=v.trim().slice(0,30);ren()}
function mgb(i){const b=S.bizs[i];if(b.mgmt=='ceo'||b.mg)return;if(use(SC[b.sc][3]))b.mg=1}
function mgAll(){S.bizs.forEach((b,i)=>mgb(i))}
function upg(i){const b=S.bizs[i];if(b.sc>=6)return;if(pay((SC[b.sc+1][2]-SC[b.sc][2])*BT[b.ty][5])){b.sc++;if(b.sc>=5)bigNews(b.name+' resmi naik status menjadi bisnis skala '+SC[b.sc][0]+'!','Bisnis',true)}}
function autoUp(i){const b=S.bizs[i];b.auto=b.auto||0;if(b.auto>=5)return;const cost=1e7*(b.auto+1)*BT[b.ty][5]*SC[b.sc][1]**.5;if(pay(cost))b.auto++}
function cloneBiz(i){const b=S.bizs[i];NB.ty=b.ty;NB.sc=b.sc;NB.mg=b.mgmt;BV='new'}
function sellB(i){const b=S.bizs[i];const payout=Math.round(bcap(b)*.6*(b.ipo?1-b.ipo.pct/100:1));S.cash+=payout;log('Menjual '+b.name+' seharga '+R(payout)+(b.ipo?' (dipotong saham publik)':''));S.bizs.splice(i,1);BV=null}
function ipoBiz(i,pct){const b=S.bizs[i];if(!b)return;if(b.sc<2)return log('Bisnis perlu skala Menengah ke atas untuk IPO');if(b.ipo)return log('Bisnis ini sudah IPO');
pct=cl(Math.round(pct||30),10,60);const val=Math.round(bcap(b)*1.4),raise=Math.round(val*pct/100);
S.ipon=(S.ipon||0)+1;b.ipo={ticker:'IPO'+S.ipon,pct,val,px:100,pv:100};S.cash+=raise;
S.ipoHist=S.ipoHist||[];S.ipoHist.unshift('Hari '+S.d+' · IPO '+b.name+' ('+b.ipo.ticker+') · +'+R(raise));if(S.ipoHist.length>15)S.ipoHist.length=15;
log('IPO '+b.name+': '+pct+'% saham publik, dana masuk '+R(raise));bigNews(b.name+' resmi melantai di bursa (IPO) dengan ticker '+b.ipo.ticker+', melepas '+pct+'% saham ke publik dan meraih dana segar '+R(raise)+'!','Bisnis',true)}
function ipoAdjust(i,dp){const b=S.bizs[i];if(!b||!b.ipo)return;const np=cl(b.ipo.pct+dp,10,70);dp=np-b.ipo.pct;if(!dp)return log('Tidak ada perubahan (batas 10%-70%)');
const amt=Math.round(Math.abs(dp)/100*b.ipo.val);
if(dp>0){S.cash+=amt}else{if(!pay(amt))return}
b.ipo.pct=np;log((dp>0?'Melepas':'Membeli balik')+' '+Math.abs(dp).toFixed(0)+'% saham '+b.ipo.ticker+' · '+R(amt))}
function ipoDelist(i){const b=S.bizs[i];if(!b||!b.ipo)return;const cost=Math.round(b.ipo.val*b.ipo.pct/100*1.1);if(!pay(cost))return;log('Delisting '+b.ipo.ticker+', kepemilikan penuh kembali · '+R(cost));delete b.ipo}
