function aucGen(){const cat=pk(['collect','collect','prop','stock','biz']);let it={id:S.auc.nextId++,cat,end:S.d+3+Math.floor(Math.random()*4),bidder:null,bidderName:'',myBid:0,hist:[]};
if(cat=='collect'){const c=pk(COL);it.name=c[0];it.val=Math.round(rn(c[1],c[2]));it.pop=c[3];it.hap=c[4];it.min=Math.round(it.val*.4)}
else if(cat=='prop'){const i=Math.floor(Math.random()*PR.length);it.pi=i;it.name=PR[i][0]+' (Sitaan)';it.val=Math.round(PR[i][1]*S.pi);it.min=Math.round(it.val*rn(.45,.65))}
else if(cat=='stock'){const a=pk(AS);const qty=Math.round(rn(3,15)*Math.max(1,1e7/a[3]));it.aid=a[0];it.qty=qty;it.name='Blok Saham '+a[0]+' ('+a[1]+')';it.val=Math.round(qty*S.px[a[0]]);it.min=Math.round(it.val*rn(.7,.85))}
else{const ty=Math.floor(Math.random()*BT.length),sc=Math.floor(Math.random()*3);it.ty=ty;it.sc=sc;it.name=BT[ty][0]+' Sitaan · '+SC[sc][0];it.val=Math.round(SC[sc][2]*BT[ty][5]);it.min=Math.round(it.val*rn(.4,.6))}
it.cur=it.min;S.auc.items.push(it);log(' Lelang baru dibuka: '+it.name)}
function aucBid(id,amt){const it=S.auc.items.find(x=>x.id==id);if(!it)return;if(it.mine)return log('Ini barang lelang Anda sendiri, tidak bisa ditawar sendiri');const minNext=Math.max(it.cur+Math.max(1e5,Math.round(it.cur*.03)),it.min);amt=Math.round(amt);if(amt<minNext)return log('Tawaran minimal '+R(minNext));
const extra=amt-(it.bidder=='you'?it.myBid:0);if(!pay(extra))return;it.cur=amt;it.bidder='you';it.myBid=amt;it.bidderName='Anda';it.hist.unshift('Anda menawar '+R(amt));if(it.hist.length>6)it.hist.length=6;log('Menawar '+it.name+' sebesar '+R(amt))}
function aucTick(){S.auc.items.forEach(it=>{if(Math.random()<.5){const inc=Math.max(1e5,Math.round(it.cur*rn(.04,.14))),nb=it.cur+inc;if(nb<=it.val*1.45){if(it.bidder=='you'){S.cash+=it.myBid;it.myBid=0}it.cur=nb;it.bidder='ai';it.bidderName=pk(BIDN);it.hist.unshift(it.bidderName+' menawar '+R(it.cur));if(it.hist.length>6)it.hist.length=6}}});
S.auc.items=S.auc.items.filter(it=>{if(S.d<it.end)return true;
if(it.cat=='sellcol'){if(it.bidder=='ai'){const fee=Math.round(it.cur*.05);S.cash+=it.cur-fee;log('Lelang "'+it.name+'" laku seharga '+R(it.cur)+' (komisi 5%: -'+R(fee)+')');S.auc.hist.unshift({d:S.d,t:it.name,r:'Terjual · '+R(it.cur-fee)+' bersih'})}
else{S.collect.push({name:it.name,val:it.val});log('Lelang "'+it.name+'" tidak laku, barang dikembalikan');S.auc.hist.unshift({d:S.d,t:it.name,r:'Tidak laku, dikembalikan'})}
if(S.auc.hist.length>20)S.auc.hist.length=20;return false}
if(it.bidder=='you'){if(it.cat=='collect'){S.collect.push({name:it.name,val:it.val});S.pop=cl(S.pop+it.pop);S.hap=cl(S.hap+it.hap)}
else if(it.cat=='prop'){S.props.push(it.pi)}
else if(it.cat=='stock'){const h=S.hold[it.aid]||(S.hold[it.aid]={q:0,c:0});h.q+=it.qty;h.c+=it.cur}
else{S.bn=(S.bn||0)+1;S.bizs.push({id:S.bn,ty:it.ty,name:BT[it.ty][0]+' #'+S.bn+' (Sitaan)',sc:it.sc,mgmt:'self',price:1,qual:1,mk:0,mg:0})}
log(' Menang lelang: '+it.name+' seharga '+R(it.cur));S.auc.hist.unshift({d:S.d,t:it.name,r:'Menang · '+R(it.cur)});if(it.val>=1e9)bigNews(uN()+' memenangkan lelang '+it.name+' senilai '+R(it.cur)+'!','Lelang',true)}
else{S.auc.hist.unshift({d:S.d,t:it.name,r:it.bidder?'Kalah, dimenangkan pihak lain seharga '+R(it.cur):'Ditutup tanpa penawar'})}
if(S.auc.hist.length>20)S.auc.hist.length=20;return false});
if(S.auc.items.length<4&&Math.random()<.3)aucGen()}
