function tf(e){const x=['jpg','jpeg','png','webp'],n=+e.dataset.n+1;if(n<x.length){e.dataset.n=n;e.src='thumb/'+e.dataset.id+'.'+x[n]}else e.remove()}
function customAmt(cb,label){const v=prompt((label||'Masukkan jumlah (Rp)')+':');if(v==null)return;const n=Math.round(parseFloat(String(v).replace(/[^0-9.]/g,'')));if(!n||n<=0)return alert('Jumlah tidak valid');cb(n)}
function customPct(cb){const v=prompt('Jual berapa persen dari posisi? (1-100):');if(v==null)return;const n=parseFloat(v);if(!n||n<=0||n>100)return alert('Masukkan angka 1-100');cb(n/100)}
function customNum(cb,label,min,max){const v=prompt(label+':');if(v==null)return;const n=parseFloat(v);if(isNaN(n)||(min!=null&&n<min)||(max!=null&&n>max))return alert('Masukkan angka'+(min!=null?' antara '+min+' dan '+max:''));cb(n)}
const pb=expr=>`<button class="b sqb" onclick="${expr};ren()">+</button>`;
let lt=null;
const spark=id=>{const h=(S.hist&&S.hist[id])||[];if(h.length<2)return'';const mn=Math.min(...h),mx=Math.max(...h),w=96,hh=30,g=mx-mn||1,pts=h.map((v,k)=>(k/(h.length-1)*w).toFixed(1)+','+(hh-2-(v-mn)/g*(hh-4)).toFixed(1)).join(' '),up=h[h.length-1]>=h[0];return `<svg width="${w}" height="${hh}" viewBox="0 0 ${w} ${hh}" style="vertical-align:middle;margin-right:6px"><polyline points="${pts}" fill="none" stroke="var(--${up?'up':'a'})" stroke-width="1.5" stroke-linejoin="round"/></svg>`};
function paintStats(){const a=19+(S.d/365|0),d=S.d%365;if($('dt'))$('dt').textContent=(S.uname?S.uname+' · ':'')+'Usia '+a+' th '+((d/30)|0)+' bln · Hari '+S.d+' ('+DN[S.d%7]+')';
if($('top'))$('top').innerHTML=`<div class="s"><small>Tunai</small><b>${R(S.cash)}</b></div><div class="s"><small>Kekayaan</small><b>${R(nw())}</b></div><div class="s"><small>Waktu tersisa</small><b>${S.hrs} jam</b></div>`+bar('Kesehatan',S.hp,'#ef4444')+bar('Bahagia',S.hap,'#22c55e')+bar('Stres',S.str,'#a855f7')+bar('Populer',S.pop,'#f59e0b')+bar('Jaringan',S.net,'#3b82f6');
if($('logs'))$('logs').innerHTML=S.logs.slice(0,3).join('<br>');}
function hubGrid(){return T.map(t=>`<button class="mi" onclick="location.href='${t[0]}.html'">${sv_(IC[t[0]],30)}<b>${t[2]}</b><span>${MS[t[0]]()}</span></button>`).join('')}
